/**
 * Internationalisation (i18n) — dictionnaires + fonction de traduction.
 *
 * Pattern inspiré des wallets open-source (locales JSON + `t()`). Langues
 * majeures couvertes ; l'anglais sert de repli si une clé manque. Les
 * traductions sont assistées et peuvent être affinées par des locuteurs natifs.
 */
import { I18nManager, Platform, NativeModules } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

export type Lang =
  | "fr"
  | "en"
  | "es"
  | "pt"
  | "de"
  | "it"
  | "nl"
  | "pl"
  | "tr"
  | "ru"
  | "ar"
  | "hi"
  | "zh"
  | "ja"
  | "ko";

export interface LangMeta {
  code: Lang;
  name: string; // nom natif
  flag: string;
  rtl?: boolean;
}

export const USER_LANGUAGE_KEY = 'user_language';

/**
 * Récupère la langue native du système.
 * 1. Tente expo-localization si le module natif est présent dans le binaire.
 * 2. Repli sur l'API Intl standard (Hermes, Web, JSC).
 * 3. Repli sur les modules natifs React Native (SettingsManager / I18nManager).
 * 4. Repli final sur 'fr'.
 */
export function getSystemLanguage(): string {
  // 1. Tente expo-localization sans planter si le binaire natif n'a pas encore été recompilé
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const ExpoLoc = require('expo-localization');
    if (typeof ExpoLoc?.getLocales === 'function') {
      const locales = ExpoLoc.getLocales();
      const code = locales?.[0]?.languageCode;
      if (code) return code.toLowerCase();
    }
  } catch {
    /* Module natif ExpoLocalization non lié dans le binaire actuel */
  }

  // 2. Intl API (Hermes engine, web, etc.)
  try {
    if (typeof Intl !== 'undefined' && Intl.DateTimeFormat) {
      const loc = Intl.DateTimeFormat().resolvedOptions().locale;
      if (loc) return loc.split(/[-_]/)[0].toLowerCase();
    }
  } catch {
    /* Intl non disponible */
  }

  // 3. React Native natif
  try {
    if (Platform.OS === 'ios') {
      const settings = NativeModules.SettingsManager?.settings;
      const appleLocale = settings?.AppleLocale || settings?.AppleLanguages?.[0];
      if (appleLocale) return appleLocale.split(/[-_]/)[0].toLowerCase();
    } else if (Platform.OS === 'android') {
      const locale = NativeModules.I18nManager?.localeIdentifier;
      if (locale) return locale.split(/[-_]/)[0].toLowerCase();
    }
  } catch {
    /* React Native NativeModules non disponible */
  }

  return 'fr';
}

/**
 * Applique la configuration RTL (droite à gauche) si la langue est arabe ou RTL.
 */
export function applyRTL(isRtl: boolean): void {
  try {
    I18nManager.allowRTL(isRtl);
    I18nManager.forceRTL(isRtl);
  } catch (e) {
    console.warn('[i18n] Error configuring RTL:', e);
  }
}

