/** Traduit une clé pour une langue, avec repli anglais. */
export function translate(lang: Lang, key: Key): string {
  return dict[lang]?.[key] ?? en[key];
}

export function isRtl(lang: Lang): boolean {
  return LANGUAGES.find((l) => l.code === lang)?.rtl ?? false;
}

/**
 * Détection synchrone initiale au démarrage.
 * Si le système est en arabe ('ar'), active immédiatement le mode RTL et renvoie 'ar'.
 * Si le système est dans une langue supportée, la renvoie.
 * Sinon repli vers la langue par défaut ('fr').
 */
export function detectInitialLanguage(): Lang {
  const systemLang = getSystemLanguage();
  if (systemLang === 'ar') {
    applyRTL(true);
    return 'ar';
  }
  const isSupported = LANGUAGES.some((l) => l.code === systemLang);
  applyRTL(false);
  return (isSupported ? systemLang : 'fr') as Lang;
}

export const systemLanguage = getSystemLanguage();
if (systemLanguage === 'ar') {
  applyRTL(true);
}

/**
 * Résout la langue finale en tenant compte des préférences enregistrées :
 * - Si l'utilisateur a déjà choisi une langue manuellement (dans AsyncStorage "user_language" ou les réglages),
 *   cette préférence prend le dessus.
 * - Sinon (premier démarrage), utilise la détection système via getLocales().
 */
export async function resolveLanguage(storedPreference?: string | null): Promise<Lang> {
  try {
    let pref = storedPreference;
    if (!pref) {
      pref = await AsyncStorage.getItem(USER_LANGUAGE_KEY);
    }
    if (pref && LANGUAGES.some((l) => l.code === pref)) {
      const lang = pref as Lang;
      applyRTL(isRtl(lang));
      return lang;
    }
  } catch {
    /* fallback to system */
  }

  return detectInitialLanguage();
}

/**
 * Remplace TOUTES les occurrences de chaque `{nom}` par sa valeur.
 *
 * Les phrases portaient des expressions de code (`${chain.name}`,
 * `${formatTokenAmount(…)}`) remplacées à la main par `.replace`, qui ne traite
 * que la PREMIÈRE occurrence : « accepts ${chain.name} » restait affiché tel
 * quel. Un `{nom}` inconnu reste visible — le test de cohérence le détecte.
 */
export function fill(text: string, vars: Record<string, string | number>): string {
  return text.replace(/\{([a-zA-Z_]+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m));
}

/** Toutes les clés (référence : l’anglais). Pour les tests de cohérence des traductions. */
export const ALL_KEYS = Object.keys(en) as Key[];
